#include <iostream>

class Counter {
public:
    explicit Counter(int v = 0) : value{v} {}

    // Prefix increment: modifies and returns *this by reference
    Counter& operator++() {
        ++value;
        return *this;
    }

    // Postfix increment: dummy int parameter, returns original by value
    Counter operator++(int) {
        Counter temp{*this};
        ++value;
        return temp;
    }

    int get() const { return value; }

private:
    int value;
};

int main() {
    Counter c{5};
    std::cout << "Initial: " << c.get() << '\n';

    Counter preResult = ++c;
    std::cout << "After ++c -> c: " << c.get() << ", returned: " << preResult.get() << '\n';

    Counter postResult = c++;
    std::cout << "After c++ -> c: " << c.get() << ", returned: " << postResult.get() << '\n';

    return 0;
}

#include <iostream>
#include <array>
#include <stdexcept>

class Date {
    friend std::ostream& operator<<(std::ostream& os, const Date& d);
public:
    Date(int m = 1, int d = 1, int y = 1900) {
        setDate(m, d, y);
    }

    void setDate(int mm, int dd, int yy) {
        if (mm < 1 || mm > 12) {
            throw std::invalid_argument("Month must be 1-12");
        }
        if (yy < 1900 || yy > 2100) {
            throw std::invalid_argument("Year must be >= 1900 and <= 2100");
        }
        if ((mm == 2 && leapYear(yy) && dd >= 1 && dd <= 29) ||
            (dd >= 1 && dd <= days[mm])) {
            month = static_cast<unsigned int>(mm);
            day = static_cast<unsigned int>(dd);
            year = static_cast<unsigned int>(yy);
        } else {
            throw std::invalid_argument("Day is out of range for month and year");
        }
    }

    static bool leapYear(int testYear) {
        return (testYear % 400 == 0) || (testYear % 100 != 0 && testYear % 4 == 0);
    }

    bool endOfMonth(int testDay) const {
        if (month == 2 && leapYear(year)) {
            return testDay == 29;
        }
        return testDay == static_cast<int>(days[month]);
    }

    Date& operator++() {
        helpIncrement();
        return *this;
    }

    Date operator++(int) {
        Date temp = *this;
        helpIncrement();
        return temp;
    }

    Date& operator+=(unsigned int additionalDays) {
        for (unsigned int i = 0; i < additionalDays; ++i) {
            helpIncrement();
        }
        return *this;
    }

private:
    unsigned int month{1};
    unsigned int day{1};
    unsigned int year{1900};

    static const std::array<unsigned int, 13> days;

    void helpIncrement() {
        if (!endOfMonth(day)) {
            ++day;
        } else if (month < 12) {
            ++month;
            day = 1;
        } else {
            ++year;
            month = 1;
            day = 1;
        }
    }
};

const std::array<unsigned int, 13> Date::days =
    {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};

std::ostream& operator<<(std::ostream& os, const Date& d) {
    os << d.year << '-' << (d.month < 10 ? "0" : "") << d.month
       << '-' << (d.day < 10 ? "0" : "") << d.day;
    return os;
}

int main() {
    Date d1{12, 27, 2010};
    std::cout << "d1: " << d1 << '\n';
    d1 += 7;
    std::cout << "d1 += 7: " << d1 << '\n';

    Date d2{2, 28, 2008};
    std::cout << "d2: " << d2 << '\n';
    std::cout << "++d2 (leap year 2008): " << ++d2 << '\n';

    Date d3{7, 13, 2010};
    std::cout << "d3: " << d3 << '\n';
    std::cout << "d3++ returned: " << d3++ << '\n';
    std::cout << "d3 after post-increment: " << d3 << '\n';

    return 0;
}
